class DialogMediator
  def initialize = @listeners = Hash.new { |h, k| h[k] = [] }
  def on(event, &block) = @listeners[event] << block
  def notify(event, payload = nil)
    @listeners[event].each { |listener| listener.call(payload) }
  end
end
hub = DialogMediator.new
hub.on(:check) { |checked| email.enabled = !checked }
hub.notify(:check, true)
